pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint256[] memory v) public {
        // Restrict to admissible domain: caller must be the required address, and arrays must have same non-zero length.
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        // Constrain v values to avoid overflow in the multiplication check.
        for (uint i = 0; i < v.length; i++) {
            vm.assume(v[i] == 0 || (v[i] * 1000000000000000000) / v[i] == 1000000000000000000);
        }
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        (bool success, bytes memory returndata) = address(c).call(abi.encodeWithSignature("transfer(address[],uint256[])", _tos, v));
        // The call must not revert (i.e., internal requires are satisfied).
        vm.assume(success);
        bool returnedValue = abi.decode(returndata, (bool));
        // The general rule: the returned value must be true.
        assertTrue(returnedValue);
    }
}

