pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint256[] memory v) public {
        // 1. Restrict to admissible domain matching the original requires
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        for (uint i = 0; i < _tos.length; i++) {
            // require(((v[i] == 0) || (((v[i] * 1000000000000000000) / v[i]) == 1000000000000000000)));
            // To avoid overflow in the assume we must check the condition similarly.
            // The multiplication overflow is avoided by checking v[i] == 0 or (v[i] * 1e18) / v[i] == 1e18.
            // Since Solidity 0.8.x reverts on overflow, we must apply the condition in the assume.
            // But we cannot call a function that reverts inside assume; instead we pre-check off chain pattern or use raw math.
            // We'll simplify: the condition is v[i] == 0 OR v[i] * 1e18 / v[i] == 1e18.
            // This means v[i] must be such that v[i] * 1e18 does not overflow a uint256, i.e., v[i] <= type(uint256).max / 1e18 ≈ 1.15e59.
            // Since v[i] is uint256, it's automatically ≤ max, but multiplication can overflow. We must ensure no overflow.
            // The requirement is exactly that if v[i] != 0, then v[i] * 1e18 does not overflow.
            // We can enforce this with bound(v[i], 0, type(uint256).max / 1e18) OR v[i] == 0.
            // But bound only takes a max; we'll use vm.assume(v[i] <= type(uint256).max / 1e18).
            // Additionally, v[i] can be 0 without condition on overflow.
            vm.assume(v[i] <= type(uint256).max / 1000000000000000000);
        }
        // 2. Set msg.sender to the required address
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        // 3. Call transfer and capture return value
        bool ret = c.transfer(_tos, v);
        // 4. Assert: for all admissible inputs, return value is true
        assertTrue(ret);
    }
}
